style.css:
/* Solid Barbie-inspired background */
body {
    background-color: #fdad86; /* light base pink/orange from your palette */
    color: #111;
    font-family: Georgia, 'Palatino Linotype', Palatino, 'Times New Roman', serif !important;
}

/* Links */
a {
    color: #ff6823; /* Summer-orange style link */
    text-decoration: underline;
    transition: all 0.3s;
}

a:hover {
    text-shadow: 0 0 8px #ff6823;
}

/* Buttons */
button, input[type="button"], input[type="submit"] {
    border: none;
    border-radius: 12px;
    padding: 6px 12px;
    cursor: pointer;
    transition: all 0.3s;
    color: #fff;
    font-family: Georgia, 'Palatino Linotype', Palatino, 'Times New Roman', serif !important;
}

/* Button color cycling by position using your palette */
button:nth-of-type(6n+1),
input[type="button"]:nth-of-type(6n+1),
input[type="submit"]:nth-of-type(6n+1) {
    background-color: #f84dae;
    box-shadow: 0 0 5px #f84dae;
}

button:nth-of-type(6n+2),
input[type="button"]:nth-of-type(6n+2),
input[type="submit"]:nth-of-type(6n+2) {
    background-color: #ff18a3;
    box-shadow: 0 0 5px #ff18a3;
}

button:nth-of-type(6n+3),
input[type="button"]:nth-of-type(6n+3),
input[type="submit"]:nth-of-type(6n+3) {
    background-color: #ff6823;
    box-shadow: 0 0 5px #ff6823;
}

button:nth-of-type(6n+4),
input[type="button"]:nth-of-type(6n+4),
input[type="submit"]:nth-of-type(6n+4) {
    background-color: #ff8348;
    box-shadow: 0 0 5px #ff8348;
}

button:nth-of-type(6n+5),
input[type="button"]:nth-of-type(6n+5),
input[type="submit"]:nth-of-type(6n+5) {
    background-color: #fdad86;
    box-shadow: 0 0 5px #fdad86;
}

button:nth-of-type(6n+6),
input[type="button"]:nth-of-type(6n+6),
input[type="submit"]:nth-of-type(6n+6) {
    background-color: #fe5e9e;
    box-shadow: 0 0 5px #fe5e9e;
}

/* Button hover glow */
button:hover, input[type="button"]:hover, input[type="submit"]:hover {
    transform: scale(1.05);
    box-shadow: 0 0 12px #fff;
}

/* Inputs */
input, textarea, select {
    border-radius: 8px;
    border: 2px solid #ff18a3;
    padding: 4px 8px;
    box-shadow: 0 0 5px #ff18a3;
    transition: all 0.3s;
    font-family: Georgia, 'Palatino Linotype', Palatino, 'Times New Roman', serif !important;
}

input:focus, textarea:focus, select:focus {
    box-shadow: 0 0 12px #ff6823;
    border-color: #ff6823;
}
